CREATE FUNCTION public.open_marketplace_conversation(application_value uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a record; cid uuid; BEGIN PERFORM public.assert_active_account(); IF NOT public.website_available() THEN RAISE EXCEPTION 'Marketplace unavailable'; END IF; SELECT ap.*,j.buyer_id,j.title INTO a FROM public.job_applications ap JOIN public.jobs j ON j.id=ap.job_id WHERE ap.id=application_value; IF NOT FOUND OR auth.uid() NOT IN(a.buyer_id,a.seller_id) THEN RAISE EXCEPTION 'Application unavailable'; END IF; IF a.status IN('withdrawn','rejected') AND NOT EXISTS(SELECT 1 FROM public.marketplace_conversations WHERE application_id=application_value) THEN RAISE EXCEPTION 'Application is no longer eligible'; END IF; INSERT INTO public.marketplace_conversations(application_id,buyer_id,seller_id,title) VALUES(a.id,a.buyer_id,a.seller_id,a.title) ON CONFLICT(application_id) DO UPDATE SET application_id=excluded.application_id RETURNING id INTO cid; RETURN cid; END $$;
CREATE FUNCTION public.send_marketplace_message(conversation_value uuid,request_value uuid,body_value text,attachment_value text DEFAULT NULL,name_value text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE mid uuid; c record; old record; BEGIN IF NOT public.conversation_participant(conversation_value) THEN RAISE EXCEPTION 'Conversation unavailable'; END IF; SELECT * INTO old FROM public.marketplace_messages WHERE sender_id=auth.uid() AND request_id=request_value; IF FOUND THEN IF old.conversation_id<>conversation_value OR old.body<>trim(body_value) OR old.attachment_path IS DISTINCT FROM attachment_value THEN RAISE EXCEPTION 'Request already used'; END IF; RETURN old.id; END IF; IF char_length(trim(body_value)) NOT BETWEEN 1 AND 4000 THEN RAISE EXCEPTION 'Enter a message of 1 to 4000 characters'; END IF; IF attachment_value IS NOT NULL AND (attachment_value NOT LIKE conversation_value::text||'/'||auth.uid()::text||'/%' OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='marketplace-files' AND name=attachment_value)) THEN RAISE EXCEPTION 'Attachment unavailable'; END IF; SELECT * INTO c FROM public.marketplace_conversations WHERE id=conversation_value; INSERT INTO public.marketplace_messages(conversation_id,sender_id,request_id,body,attachment_path,attachment_name) VALUES(conversation_value,auth.uid(),request_value,trim(body_value),attachment_value,left(name_value,150)) ON CONFLICT(sender_id,request_id) DO NOTHING RETURNING id INTO mid; IF mid IS NULL THEN SELECT id INTO mid FROM public.marketplace_messages WHERE sender_id=auth.uid() AND request_id=request_value AND conversation_id=conversation_value; RETURN mid; END IF; INSERT INTO public.marketplace_notifications(user_id,conversation_id,kind) VALUES(CASE WHEN c.buyer_id=auth.uid() THEN c.seller_id ELSE c.buyer_id END,conversation_value,'message'); RETURN mid; END $$;
CREATE FUNCTION public.read_marketplace_conversation(conversation_value uuid,through_value timestamptz) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.conversation_participant(conversation_value) THEN RAISE EXCEPTION 'Conversation unavailable'; END IF; INSERT INTO public.marketplace_reads VALUES(conversation_value,auth.uid(),least(through_value,now())) ON CONFLICT(conversation_id,user_id) DO UPDATE SET read_at=greatest(marketplace_reads.read_at,excluded.read_at); UPDATE public.marketplace_notifications SET read_at=now() WHERE user_id=auth.uid() AND conversation_id=conversation_value AND created_at<=through_value AND read_at IS NULL; END $$;
CREATE FUNCTION public.mark_marketplace_notification(notification_value uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.assert_active_account(); IF NOT public.website_available() THEN RAISE EXCEPTION 'Marketplace unavailable'; END IF; UPDATE public.marketplace_notifications SET read_at=now() WHERE id=notification_value AND user_id=auth.uid(); END $$;
REVOKE ALL ON FUNCTION public.open_marketplace_conversation(uuid),public.send_marketplace_message(uuid,uuid,text,text,text),public.read_marketplace_conversation(uuid,timestamptz),public.mark_marketplace_notification(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.open_marketplace_conversation(uuid),public.send_marketplace_message(uuid,uuid,text,text,text),public.read_marketplace_conversation(uuid,timestamptz),public.mark_marketplace_notification(uuid) TO authenticated;
CREATE POLICY marketplace_file_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='marketplace-files' AND public.conversation_participant((storage.foldername(name))[1]::uuid) AND (storage.foldername(name))[2]=auth.uid()::text);
CREATE POLICY marketplace_file_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='marketplace-files' AND public.conversation_participant((storage.foldername(name))[1]::uuid));
CREATE POLICY marketplace_file_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='marketplace-files' AND (storage.foldername(name))[2]=auth.uid()::text AND public.conversation_participant((storage.foldername(name))[1]::uuid) AND NOT EXISTS(SELECT 1 FROM public.marketplace_messages WHERE attachment_path=name));